#include <cstdio>
#include <cstdlib>

void RequireLive(bool ok,const char* message){if(!ok){std::fprintf(stderr,"FAIL: %s\n",message);throw std::runtime_error(message);}}
struct Resources {DWORD handles=0,gdi=0,user=0;SIZE_T privateBytes=0,workingSet=0;ULONGLONG cpu=0;};
Resources ResourcesNow(){Resources r;auto process=GetCurrentProcess();GetProcessHandleCount(process,&r.handles);r.gdi=GetGuiResources(process,GR_GDIOBJECTS);r.user=GetGuiResources(process,GR_USEROBJECTS);PROCESS_MEMORY_COUNTERS_EX memory{};if(GetProcessMemoryInfo(process,reinterpret_cast<PROCESS_MEMORY_COUNTERS*>(&memory),sizeof(memory))){r.privateBytes=memory.PrivateUsage;r.workingSet=memory.WorkingSetSize;}FILETIME created{},exit{},kernel{},user{};GetProcessTimes(process,&created,&exit,&kernel,&user);ULARGE_INTEGER a{},b{};a.LowPart=kernel.dwLowDateTime;a.HighPart=kernel.dwHighDateTime;b.LowPart=user.dwLowDateTime;b.HighPart=user.dwHighDateTime;r.cpu=a.QuadPart+b.QuadPart;return r;}
void PumpFor(DWORD milliseconds){ULONGLONG end=GetTickCount64()+milliseconds;do{MSG message{};while(PeekMessageW(&message,nullptr,0,0,PM_REMOVE)){if(message.message!=WM_QUIT){TranslateMessage(&message);DispatchMessageW(&message);}}MsgWaitForMultipleObjectsEx(0,nullptr,4,QS_ALLINPUT,MWMO_INPUTAVAILABLE);}while(GetTickCount64()<end);}
void Settle(Island& app){ULONGLONG end=GetTickCount64()+3000;while(app.scheduler.active&&GetTickCount64()<end)PumpFor(10);RequireLive(!app.scheduler.active&&!app.frameClock.Active(),"motion settles and releases its frame thread");RequireLive(!app.previousPane,"settled transition releases its outgoing bitmap");}
void SaveFrame(Island& app,const std::filesystem::path& path){std::vector<unsigned char> pixels;UINT width=0,height=0;if(FAILED(app.composition.ReadPixels(pixels,width,height)))return;ComPtr<IWICImagingFactory> images;Check(CoCreateInstance(CLSID_WICImagingFactory,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&images)));ComPtr<IWICStream> stream;Check(images->CreateStream(&stream));Check(stream->InitializeFromFilename(path.c_str(),GENERIC_WRITE));ComPtr<IWICBitmapEncoder> encoder;Check(images->CreateEncoder(GUID_ContainerFormatPng,nullptr,&encoder));Check(encoder->Initialize(stream.Get(),WICBitmapEncoderNoCache));ComPtr<IWICBitmapFrameEncode> frame;Check(encoder->CreateNewFrame(&frame,nullptr));Check(frame->Initialize(nullptr));Check(frame->SetSize(width,height));WICPixelFormatGUID format=GUID_WICPixelFormat32bppBGRA;Check(frame->SetPixelFormat(&format));Check(frame->WritePixels(height,width*4,static_cast<UINT>(pixels.size()),pixels.data()));Check(frame->Commit());Check(encoder->Commit());}
