        app.currentMedia.title=L"Fixture music";app.currentMedia.artist=L"Fixture artist";app.currentMedia.available=app.currentMedia.canPlay=app.currentMedia.canPrevious=app.currentMedia.canNext=true;app.currentMedia.duration=180;app.currentMedia.position=40;
