        for(int i=0;i<1000;++i)app.feedback[L"fixture-finished:"+std::to_wstring(i)]={};app.ArmMotion();PumpFor(20);Settle(app);RequireLive(app.feedback.size()<16,"settled one-shot feedback does not grow across distinct items");
