        RequireLive(!app.scheduler.active&&!app.target&&!app.composition.Active(),"stalled collapse releases GPU targets");
        app.SetExpanded(true);Settle(app);app.reducedMotion=true;app.SetExpanded(false);
        RequireLive(!app.target&&!app.composition.Active(),"reduced-motion collapse releases GPU targets");
        app.reducedMotion=false;app.SetExpanded(true);Settle(app);report<<"stalled_and_reduced_motion_gpu_release=PASS\n";
        // Record our own transparent swapchain only. Recording is excluded from timing.
