        for(int view:(quick?std::vector<int>{0}:std::vector<int>{0,1,2,3,4,5,6,0})){app.SetTab(static_cast<Tab>(view));if(view==4){app.railPointer.goal=app.LayoutWidth()/2;app.railStrength.goal=1;}if(view==5){app.wallpaperParallax.goal=.7f;app.SetAccent(0x83B8DE);}PumpFor(420);}if(!quick){app.OpenFlyout(Flyout::Wifi);app.selectedWifi=0;PumpFor(420);app.OpenFlyout(Flyout::Bluetooth);app.selectedBluetooth=0;PumpFor(420);app.SetTab(Tab::Controls);app.miniMode=true;app.SetExpanded(true);PumpFor(420);Settle(app);app.miniMode=false;app.SetExpanded(true);}Settle(app);app.beforePresent={};report<<"recorded_swapchain_frames="<<frames<<"\n";
        app.frameIntervals.clear();app.paintTimes.clear();
