            validStatistics=false;app.SetExpanded(true);for(int v:{0,1,2,3,4,5,6,0}){app.SetTab(static_cast<Tab>(v));PumpFor(24);}if(!quick){app.OpenFlyout(Flyout::Wifi);app.selectedWifi=0;PumpFor(24);app.OpenFlyout(Flyout::Bluetooth);app.selectedBluetooth=0;PumpFor(24);app.SetTab(Tab::Controls);app.miniMode=true;app.SetExpanded(true);PumpFor(24);app.miniMode=false;app.SetTab(Tab::Controls);}
